// --- CLEAN ORTHOGONALLY ROUTED WATER NETWORK SVG GENERATOR ---
const pythonData = $('Pinch Cal').first().json;
const ops = pythonData.operations_data || [];
const totalFreshwater = pythonData.min_freshwater_requirement_t_hr;

// 1. Gather outputs from the merged branches
let graph1Url = "";
let graph2Url = "";
let graph1B64 = "";
let graph2B64 = "";
let anthropicText = "";

const allItems = $input.all();
allItems.forEach(item => {
  const data = item.json;
  if (data.url && !graph1Url) graph1Url = data.url;
  else if (data.url && graph1Url) graph2Url = data.url;
  if (data.graph1_base64) graph1B64 = String(data.graph1_base64).trim();
  if (data.graph2_base64) graph2B64 = String(data.graph2_base64).trim();
  if (data.text || data.output) {
    anthropicText = data.text || data.output;
  }
});

if (!anthropicText) {
  try {
    anthropicText = $('Basic LLM Chain').first().json.text || $('Basic LLM Chain').first().json.output || "";
  } catch(e) {}
}

// 2. Extract Dynamic JSON Routing Matrix from Anthropic's response
let routing = { freshwater_splits: [], reuse_streams: [], wastewater_streams: [] };
const jsonMatch = anthropicText.match(/```json\s*([\s\S]*?)\s*```/);
if (jsonMatch && jsonMatch[1]) {
  try {
    routing = JSON.parse(jsonMatch[1]);
  } catch(e) {}
}

// 3. Dynamically Generate SVG Layout with Routed Paths
const numOps = ops.length;
const W = Math.max(1100, numOps * 260);
const H = 750;

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

function drawBox(x, y, w, h, lines, fill, stroke, color) {
  let out = `<rect x="${x - w/2}" y="${y - h/2}" width="${w}" height="${h}" rx="10" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;
  const lh = 18;
  const startY = y - (lines.length - 1) * (lh / 2);
  lines.forEach((l, i) => {
    out += `<text x="${x}" y="${startY + i * lh}" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" fill="${color}" font-weight="bold">${esc(l)}</text>`;
  });
  return out;
}

// Straight arrow for freshwater and direct drops
function drawStraightArrow(x1, y1, x2, y2, color, label, labelOffsetX = 0, labelOffsetY = -8) {
  const id = 'arr_' + color.replace('#', '');
  let out = `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2" marker-end="url(#${id})"/>`;
  if (label !== undefined && label !== null) {
    const mx = (x1 + x2) / 2 + labelOffsetX;
    const my = (y1 + y2) / 2 + labelOffsetY;
    out += `<text x="${mx}" y="${my}" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="${color}" font-weight="bold">${esc(label)}</text>`;
  }
  return out;
}

// Routed orthogonal path for reuse/bypass lines to prevent box overlap
function drawRoutedPath(x1, y1, x2, y2, color, label, routingOffset = 0) {
  const id = 'arr_' + color.replace('#', '');
  const baseRouteY = 360 + routingOffset; // Distinct vertical channel below boxes

  // Orthogonal path: Down from source -> Horizontal across channel -> Up to destination
  const pathData = `M ${x1} ${y1} L ${x1} ${baseRouteY} L ${x2} ${baseRouteY} L ${x2} ${y2}`;

  let out = `<path d="${pathData}" fill="none" stroke="${color}" stroke-width="2" marker-end="url(#${id})"/>`;

  if (label !== undefined && label !== null) {
    // Place label neatly along the horizontal segment of the routed path
    const midX = (x1 + x2) / 2;
    out += `<text x="${midX}" y="${baseRouteY - 5}" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="${color}" font-weight="bold">${esc(label)}</text>`;
  }
  return out;
}

let svgElements = '';
let defs = '<defs>';
['#0284c7', '#333333', '#ea580c'].forEach(c => {
  defs += `<marker id="arr_${c.replace('#', '')}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="${c}"/></marker>`;
});
defs += '</defs>';

// Title
svgElements += `<text x="${W/2}" y="35" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="bold" fill="#1e293b">Dynamic Proposed Water Allocation Network</text>`;

// Freshwater Header Box
const fwX = W / 2;
const fwY = 90;
svgElements += drawBox(fwX, fwY, 180, 50, ['Freshwater Supply', `${totalFreshwater} t/hr`], '#e0f2fe', '#0284c7', '#0369a1');

// Operation Boxes
const opCoords = {};
const spacing = W / (numOps + 1);
const opY = 250;

ops.forEach((o, i) => {
  const opName = `Op ${o.op}`;
  const opX = spacing * (i + 1);
  opCoords[opName] = { x: opX, y: opY };
  svgElements += drawBox(opX, opY, 130, 65, [`Operation ${o.op}`, `${o.flow} t/hr`], '#d8f3dc', '#2d6a4f', '#1b4332');
});

// Wastewater Box
const wwX = W / 2;
const wwY = 600;
svgElements += drawBox(wwX, wwY, 220, 50, ['Wastewater Collection', `${totalFreshwater} t/hr`], '#ffedd5', '#ea580c', '#c2410c');

// 1. Draw Freshwater Splits (Top fan-out)
(routing.freshwater_splits || []).forEach((item, index) => {
  const target = opCoords[item.to];
  if (target) {
    const offsetX = (index - (numOps - 1) / 2) * 40;
    svgElements += drawStraightArrow(fwX, fwY + 25, target.x, target.y - 32.5, '#0284c7', `${item.flow} t/hr`, offsetX, -5);
  }
});

// 2. Draw Reuse Streams using Clean Downward Routed Paths (Side-by-side channels)
(routing.reuse_streams || []).forEach((item, index) => {
  const src = opCoords[item.from];
  const dst = opCoords[item.to];
  if (src && dst) {
    // Route from bottom of source operation to bottom of destination operation, offset vertically per stream
    const routingOffset = index * 22; 
    svgElements += drawRoutedPath(src.x, src.y + 32.5, dst.x, dst.y + 32.5, '#333333', `${item.flow} t/hr`, routingOffset);
  }
});

// 3. Draw Wastewater Discharges (Fan-in to bottom box)
const allWW = routing.wastewater_streams || [];
allWW.forEach((item, index) => {
  const src = opCoords[item.from];
  if (src) {
    const targetWWX = wwX - 70 + (140 / Math.max(1, allWW.length - 1)) * index;
    const labelShiftX = (index - (allWW.length - 1) / 2) * 25;
    svgElements += drawStraightArrow(src.x, src.y + 32.5, targetWWX, wwY - 25, '#ea580c', `${item.flow} t/hr`, labelShiftX, 5);
  }
});

const finalSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${defs}<rect width="100%" height="100%" fill="#ffffff"/>${svgElements}</svg>`;
const networkSvgB64 = Buffer.from(finalSvg, 'utf8').toString('base64');

return [{
  json: {
    "1_Graph_1_URL": graph1Url || "",
    "2_Graph_2_URL": graph2Url || "",
    "3_Anthropic_Analysis_Text": anthropicText,
    "4_Dynamic_Network_SVG_Base64": networkSvgB64
  },
  binary: {
    ...(graph1B64 ? { graph1: { data: graph1B64, mimeType: 'image/png', fileName: 'graph1.png', fileExtension: 'png' } } : {}),
    ...(graph2B64 ? { graph2: { data: graph2B64, mimeType: 'image/png', fileName: 'graph2.png', fileExtension: 'png' } } : {}),
    network_diagram: {
      data: networkSvgB64,
      mimeType: 'image/svg+xml',
      fileName: 'dynamic_water_network.svg',
      fileExtension: 'svg'
    }
  }
}];
